#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int priority;
    int id;
} TestCase;

TestCase *new_TestCase(int id) {
    TestCase *testcase = (TestCase *) malloc(sizeof(TestCase));
    testcase->priority = 0;
    testcase->id = id;
    return testcase;
}

int cmp(const void *a, const void *b) {
    TestCase *A = *((TestCase **) a);
    TestCase *B = *((TestCase **) b);
    return A->priority != B->priority ? B->priority - A->priority : A->id - B->id;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    int features[n + 1];
    for (int i = 1; i <= n; i++) {
        scanf("%d", &features[i]);
    }

    TestCase *cases[m];
    for (int i = 0; i < m; i++) {
        cases[i] = new_TestCase(i + 1);

        int feature_id;
        while (scanf("%d", &feature_id)) {
            cases[i]->priority += features[feature_id];
            if (getchar() != ' ') break;
        }
    }

    qsort(cases, m, sizeof(TestCase *), cmp);

    for (int i = 0; i < m; i++) {
        printf("%d\n", cases[i]->id);
    }

    return 0;
}
